# Read the HTML file
with open('/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_ENHANCED.html', 'r') as f:
    html_content = f.read()

# Find all cover image tags
cover_img_pattern = r'<img src="/home/bob/books/The_Unwritten_Future/generated_images/cover.png" alt="Book Cover" style="[^"]*">'
matches = list(re.finditer(cover_img_pattern, html_content))

if len(matches) > 1:
    # Keep the first one that appears after the cover div
    cover_div_end = html_content.find('</div>', html_content.find('<div class="cover">'))
    if cover_div_end != -1:
        # Find the first cover img after cover div
        first_valid_img = None
        for match in matches:
            if match.start() > cover_div_end:
                first_valid_img = match
                break
        if first_valid_img:
            # Remove all others
            for match in matches:
                if match != first_valid_img:
                    html_content = html_content.replace(match.group(0), '')
            print(f"Removed {len(matches)-1} duplicate cover images")
else:
    print("No duplicates to remove")

# Write back
with open('/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_ENHANCED.html', 'w') as f:
